fn retained_macro_definitions_mention_unqualified_ident(
    project: &Project,
    reduced: &ReducedProject,
    render_plan: Option<&RenderPlan>,
    package: &str,
    module_path: &[String],
    ident: &str,
) -> bool {
    let Some(items) = module_items_for_path(project, package, module_path) else {
        return false;
    };

    items.iter().any(|item| {
        let Item::Macro(item_macro) = item else {
            return false;
        };
        let Some(name) = item_macro_definition_name(item_macro) else {
            return false;
        };
        let definition_is_reachable = render_plan.map_or_else(
            || {
                reachable_module_mentions_ident(project, reduced, package, module_path, &name)
                    || reachable_package_mentions_ident(project, reduced, package, &name)
            },
            |render_plan| {
                render_plan.module_mentions_ident(package, module_path, &name)
                    || render_plan.package_mentions_ident(package, &name)
            },
        );
        definition_is_reachable
            && token_stream_mentions_unqualified_ident(&item_macro.mac.tokens, ident)
    })
}

fn item_macro_definition_name(item_macro: &syn::ItemMacro) -> Option<String> {
    if let Some(ident) = &item_macro.ident {
        return Some(ident.to_string());
    }
    if !item_macro.mac.path.is_ident("macro_rules") {
        return None;
    }
    item_macro.mac.tokens.clone().into_iter().find_map(|token| {
        let TokenTree::Ident(ident) = token else {
            return None;
        };
        Some(ident.to_string())
    })
}

fn collect_retained_module_surface_idents(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    module_path: &[String],
    items: &[Item],
    reachable_token_idents: &ReachableTokenIdentIndex,
    idents: &mut BTreeSet<String>,
) {
    let retained_macro_definitions = retained_macro_definitions_for_generated_items(
        project,
        reduced,
        package,
        module_path,
        items,
    );
    let aliases = project
        .module_aliases
        .get(&(package.to_string(), module_path.to_vec()))
        .cloned()
        .unwrap_or_default();

    for item in items {
        match item {
            Item::ForeignMod(_) => {}
            Item::Impl(item_impl) => {
                let has_reachable_method = impl_has_reachable_method(
                    project,
                    reduced,
                    package,
                    module_path,
                    item_impl,
                    &aliases,
                );
                if has_reachable_method {
                    collect_impl_header_idents(item_impl, idents);
                    for attr in &item_impl.attrs {
                        collect_token_idents(&attr.to_token_stream(), idents);
                    }
                    for impl_item in &item_impl.items {
                        if root_macro_impl_surface_should_render_for_module(
                            project,
                            reduced,
                            package,
                            module_path,
                            item_impl,
                            &aliases,
                        ) && root_macro_impl_item_should_render(item_impl, impl_item)
                        {
                            if !impl_item_is_test(impl_item) {
                                collect_token_idents(&impl_item.to_token_stream(), idents);
                            }
                        } else if !matches!(impl_item, ImplItem::Fn(_))
                            && !impl_item_is_test(impl_item)
                        {
                            collect_token_idents(&impl_item.to_token_stream(), idents);
                        }
                    }
                }
                if item_impl.trait_.is_some()
                    && impl_should_render(
                        project,
                        reduced,
                        package,
                        module_path,
                        item_impl,
                        &aliases,
                    )
                {
                    collect_impl_header_idents(item_impl, idents);
                    for attr in &item_impl.attrs {
                        collect_token_idents(&attr.to_token_stream(), idents);
                    }
                    for impl_item in &item_impl.items {
                        if !impl_item_is_test(impl_item) {
                            collect_token_idents(&impl_item.to_token_stream(), idents);
                        }
                    }
                }
            }
            Item::Macro(item_macro)
                if macro_definition_should_remain(item_macro, &retained_macro_definitions) =>
            {
                collect_token_idents(&item_macro.mac.tokens, idents);
            }
            Item::Macro(item_macro)
                if item_macro.ident.is_none()
                    && should_retain_macro_invocation(
                        project,
                        reduced,
                        package,
                        module_path,
                        item_macro,
                    ) =>
            {
                collect_token_idents(&item_macro.mac.tokens, idents);
            }
            _ => {}
        }
    }
    expand_alias_surface_idents(&aliases, idents);

    for item in items {
        let Item::ForeignMod(foreign_mod) = item else {
            continue;
        };
        for foreign_item in &foreign_mod.items {
            if foreign_item_feeds_reachable_code_from_index(
                reachable_token_idents,
                package,
                module_path,
                idents,
                foreign_item,
            ) {
                collect_token_idents(&foreign_item.to_token_stream(), idents);
            }
        }
    }
    expand_alias_surface_idents(&aliases, idents);
}

fn foreign_item_feeds_reachable_code_from_index(
    reachable_token_idents: &ReachableTokenIdentIndex,
    package: &str,
    module_path: &[String],
    module_surface_idents: &BTreeSet<String>,
    foreign_item: &ForeignItem,
) -> bool {
    let Some(name) = foreign_item_name(foreign_item) else {
        return false;
    };
    module_surface_idents.contains(&name)
        || reachable_token_idents.module_mentions_ident(package, module_path, &name)
        || reachable_token_idents.package_mentions_ident(package, &name)
}

fn foreign_item_feeds_reachable_code(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    module_path: &[String],
    foreign_item: &ForeignItem,
) -> bool {
    let Some(name) = foreign_item_name(foreign_item) else {
        return false;
    };
    reachable_module_mentions_ident(project, reduced, package, module_path, &name)
        || reachable_package_mentions_ident(project, reduced, package, &name)
}

fn retained_foreign_items_mention_unqualified_ident(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    module_path: &[String],
    ident: &str,
) -> bool {
    module_items_for_path(project, package, module_path).is_some_and(|items| {
        items.iter().any(|item| {
            let Item::ForeignMod(foreign_mod) = item else {
                return false;
            };
            foreign_mod.items.iter().any(|foreign_item| {
                foreign_item_feeds_reachable_code(
                    project,
                    reduced,
                    package,
                    module_path,
                    foreign_item,
                ) && token_stream_mentions_unqualified_ident(&foreign_item.to_token_stream(), ident)
            })
        })
    })
}

fn retained_foreign_items_mention_unqualified_ident_in_plan(
    project: &Project,
    render_plan: &RenderPlan,
    package: &str,
    module_path: &[String],
    ident: &str,
) -> bool {
    module_items_for_path(project, package, module_path).is_some_and(|items| {
        items.iter().any(|item| {
            let Item::ForeignMod(foreign_mod) = item else {
                return false;
            };
            foreign_mod.items.iter().any(|foreign_item| {
                foreign_item_feeds_render_plan(render_plan, package, module_path, foreign_item)
                    && token_stream_mentions_unqualified_ident(
                        &foreign_item.to_token_stream(),
                        ident,
                    )
            })
        })
    })
}

fn foreign_item_feeds_render_plan(
    render_plan: &RenderPlan,
    package: &str,
    module_path: &[String],
    foreign_item: &ForeignItem,
) -> bool {
    let Some(name) = foreign_item_name(foreign_item) else {
        return false;
    };
    render_plan.module_mentions_ident(package, module_path, &name)
        || render_plan.package_mentions_ident(package, &name)
}

fn collect_impl_header_idents(item_impl: &syn::ItemImpl, idents: &mut BTreeSet<String>) {
    collect_token_idents(&item_impl.generics.to_token_stream(), idents);
    collect_token_idents(&item_impl.self_ty.to_token_stream(), idents);
    if let Some((_, trait_path, _)) = &item_impl.trait_ {
        collect_token_idents(&trait_path.to_token_stream(), idents);
    }
}

fn collect_impl_header_unqualified_idents(
    item_impl: &syn::ItemImpl,
    idents: &mut BTreeSet<String>,
) {
    collect_token_unqualified_idents(&item_impl.generics.to_token_stream(), idents);
    collect_token_unqualified_idents(&item_impl.self_ty.to_token_stream(), idents);
    if let Some((_, trait_path, _)) = &item_impl.trait_ {
        collect_token_unqualified_idents(&trait_path.to_token_stream(), idents);
    }
}

fn impl_has_reachable_method(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    module_path: &[String],
    item_impl: &syn::ItemImpl,
    aliases: &std::collections::HashMap<String, Vec<String>>,
) -> bool {
    let Some(type_path) =
        resolved_local_type_path(project, package, module_path, &item_impl.self_ty, aliases)
    else {
        return false;
    };
    if root_item_impl_surface_should_render(reduced, package, &type_path, item_impl) {
        return true;
    }
    let trait_path = item_impl
        .trait_
        .as_ref()
        .map(|(_, path, _)| normalized_path(module_path, path, aliases));
    let trait_input_type_paths = item_impl
        .trait_
        .as_ref()
        .map(|(_, path, _)| trait_input_type_paths(module_path, path, aliases))
        .unwrap_or_default();

    item_impl.items.iter().any(|impl_item| {
        let ImplItem::Fn(method) = impl_item else {
            return false;
        };
        let id = CallableId::Method {
            package: package.to_string(),
            type_path: type_path.clone(),
            trait_path: trait_path.clone(),
            trait_input_type_paths: trait_input_type_paths.clone(),
            method: method.sig.ident.to_string(),
        };
        reduced.reachable.contains(&id)
    })
}

fn impl_should_render(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    module_path: &[String],
    item_impl: &syn::ItemImpl,
    aliases: &std::collections::HashMap<String, Vec<String>>,
) -> bool {
    if impl_has_reachable_method(project, reduced, package, module_path, item_impl, aliases) {
        return true;
    }
    let Some(type_path) =
        resolved_local_type_path(project, package, module_path, &item_impl.self_ty, aliases)
    else {
        return false;
    };
    let trait_path = item_impl
        .trait_
        .as_ref()
        .map(|(_, path, _)| normalized_path(module_path, path, aliases));
    let resolved_trait = item_impl.trait_.as_ref().and_then(|(_, path, _)| {
        resolve_trait_path_for_impl(project, package, module_path, path, aliases)
    });
    let trait_input_type_paths = item_impl
        .trait_
        .as_ref()
        .map(|(_, path, _)| trait_input_type_paths(module_path, path, aliases))
        .unwrap_or_default();
    let trait_impl_is_required = trait_path.as_ref().is_some_and(|trait_path| {
        trait_impl_items_are_reachable(reduced, package, &type_path, trait_path)
    });
    let kept_trait_assoc_item =
        resolved_trait
            .as_ref()
            .is_some_and(|(trait_package, trait_path)| {
                item_impl.items.iter().any(|impl_item| {
                    if impl_item_is_test(impl_item) {
                        return false;
                    }
                    let Some((name, _kind)) = impl_item_assoc_name_kind(impl_item) else {
                        return false;
                    };
                    trait_impl_assoc_item_should_remain_for_references_to_trait(
                        project,
                        reduced,
                        package,
                        &type_path,
                        trait_package,
                        trait_path,
                        &trait_input_type_paths,
                        &name,
                    )
                })
            });
    let marker_trait_impl_is_required = trait_path
        .as_ref()
        .and_then(|path| path.last())
        .is_some_and(|trait_name| {
            marker_trait_impl_should_remain(reduced, package, &type_path, trait_name)
        })
        && item_impl
            .items
            .iter()
            .filter(|impl_item| !impl_item_is_test(impl_item))
            .all(|impl_item| !matches!(impl_item, ImplItem::Fn(_)));

    trait_impl_is_required || kept_trait_assoc_item || marker_trait_impl_is_required
}

#[allow(clippy::too_many_arguments)]
fn impl_surface_should_render(
    project: &Project,
    reduced: &ReducedProject,
    render_plan: &RenderPlan,
    package: &str,
    module_path: &[String],
    type_path: &[String],
    trait_path: Option<&[String]>,
    resolved_trait: Option<(&str, &[String])>,
    trait_input_type_paths: &[Vec<String>],
    trait_item: Option<&ItemId>,
    item_impl: &syn::ItemImpl,
) -> bool {
    let kept_method = item_impl.items.iter().any(|impl_item| {
        let ImplItem::Fn(method) = impl_item else {
            return false;
        };
        if impl_item_is_test(impl_item) {
            return false;
        }
        let id = CallableId::Method {
            package: package.to_string(),
            type_path: type_path.to_vec(),
            trait_path: trait_path.map(<[String]>::to_vec),
            trait_input_type_paths: trait_input_type_paths.to_vec(),
            method: method.sig.ident.to_string(),
        };
        render_plan.callable_should_render(&id)
            || render_plan.retained_impl_surfaces_call_inherent_associated_function(
                package,
                type_path,
                &method.sig.ident.to_string(),
            )
    });
    let kept_inherent_assoc_item = trait_path.is_none()
        && item_impl.items.iter().any(|impl_item| {
            inherent_impl_assoc_item_should_render(
                project,
                reduced,
                render_plan,
                package,
                module_path,
                type_path,
                item_impl,
                impl_item,
            )
        });
    let kept_trait_assoc_item = resolved_trait.is_some_and(|(trait_package, trait_path)| {
        item_impl.items.iter().any(|impl_item| {
            if impl_item_is_test(impl_item) {
                return false;
            }
            let Some((name, _kind)) = impl_item_assoc_name_kind(impl_item) else {
                return false;
            };
            trait_impl_assoc_item_should_remain_for_references_to_trait(
                project,
                reduced,
                package,
                type_path,
                trait_package,
                trait_path,
                trait_input_type_paths,
                &name,
            )
        })
    });
    let trait_impl_is_required = trait_path.is_some_and(|trait_path| {
        trait_impl_items_are_reachable(reduced, package, type_path, trait_path)
    });
    let default_trait_impl_is_required = trait_item.is_some_and(|trait_item| {
        reduced.reachable_items.contains(trait_item)
            && trait_default_method_is_referenced_by_reachable_callables(
                project, reduced, trait_item,
            )
            && trait_impl_self_type_is_referenced_by_reachable_surface(
                project, reduced, package, type_path,
            )
    });
    let marker_trait_impl_is_required =
        trait_path
            .and_then(|path| path.last())
            .is_some_and(|trait_name| {
                marker_trait_impl_should_remain(reduced, package, type_path, trait_name)
            })
            && item_impl
                .items
                .iter()
                .filter(|impl_item| !impl_item_is_test(impl_item))
                .all(|impl_item| !matches!(impl_item, ImplItem::Fn(_)));
    let root_macro_impl_surface_is_required =
        render_plan.root_item_impl_surface_should_render(reduced, package, type_path, item_impl);

    kept_method
        || kept_inherent_assoc_item
        || kept_trait_assoc_item
        || trait_impl_is_required
        || default_trait_impl_is_required
        || marker_trait_impl_is_required
        || root_macro_impl_surface_is_required
}

#[allow(clippy::too_many_arguments)]
fn impl_item_should_render_for_trait_surface(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    type_path: &[String],
    trait_path: Option<&[String]>,
    resolved_trait: Option<(&str, &[String])>,
    trait_input_type_paths: &[Vec<String>],
    trait_item: Option<&ItemId>,
    item_impl: &syn::ItemImpl,
    impl_item: &ImplItem,
) -> bool {
    if impl_item_is_test(impl_item) {
        return false;
    }
    if item_impl
        .attrs
        .iter()
        .any(attr_requires_impl_surface_retention)
    {
        return true;
    }
    if impl_item_attrs_require_surface_retention(impl_item) {
        return true;
    }
    let resolved_trait_item = resolved_trait.and_then(|(trait_package, trait_path)| {
        trait_item_for_package_path(project, trait_package, trait_path)
    });
    let trait_contract = trait_item.or(resolved_trait_item.as_ref());
    if trait_contract.is_some_and(|trait_item| {
        trait_impl_item_is_required_by_trait(project, trait_item, impl_item)
    }) {
        return true;
    }
    if let (Some((trait_package, resolved_trait_path)), Some((name, _kind))) =
        (resolved_trait, impl_item_assoc_name_kind(impl_item))
    {
        if trait_impl_assoc_item_should_remain_for_references_to_trait(
            project,
            reduced,
            package,
            type_path,
            trait_package,
            resolved_trait_path,
            trait_input_type_paths,
            &name,
        ) {
            return true;
        }
    }
    if let (Some(trait_item), Some(_trait_path), Some((name, _kind))) = (
        trait_contract,
        trait_path,
        impl_item_assoc_name_kind(impl_item),
    ) {
        if trait_default_method_assoc_item_override_should_render(
            project, reduced, package, type_path, trait_item, &name,
        ) {
            return true;
        }
    }
    if trait_path.is_some()
        && trait_contract.is_none()
        && impl_item_assoc_name_kind(impl_item).is_some()
    {
        return true;
    }
    let (Some(trait_path), ImplItem::Fn(method)) = (trait_path, impl_item) else {
        return trait_contract.is_none() && resolved_trait.is_none();
    };
    let id = CallableId::Method {
        package: package.to_string(),
        type_path: type_path.to_vec(),
        trait_path: Some(trait_path.to_vec()),
        trait_input_type_paths: trait_input_type_paths.to_vec(),
        method: method.sig.ident.to_string(),
    };
    reduced.reachable.contains(&id)
}

#[allow(clippy::too_many_arguments)]
fn inherent_impl_assoc_item_should_render(
    project: &Project,
    reduced: &ReducedProject,
    render_plan: &RenderPlan,
    package: &str,
    module_path: &[String],
    type_path: &[String],
    item_impl: &syn::ItemImpl,
    impl_item: &ImplItem,
) -> bool {
    if impl_item_is_test(impl_item) {
        return false;
    }
    let Some((name, _kind)) = impl_item_assoc_name_kind(impl_item) else {
        return false;
    };
    if !path_item_should_render(render_plan, package, type_path, type_surface_item_kinds()) {
        return false;
    }
    if item_impl
        .attrs
        .iter()
        .any(attr_requires_impl_surface_retention)
    {
        return render_plan
            .root_item_impl_surface_should_render(reduced, package, type_path, item_impl)
            && root_macro_impl_item_should_render(item_impl, impl_item);
    }
    if impl_item_attrs_require_surface_retention(impl_item) {
        return true;
    }
    if source_include_blocked_impl_method_should_render(
        project,
        reduced,
        render_plan,
        package,
        type_path,
        item_impl,
        &name,
    ) {
        return true;
    }
    reachable_reduced_callables_reference_inherent_assoc_item(
        project, reduced, package, type_path, &name,
    ) || rendered_items_reference_inherent_assoc_item(
        project,
        render_plan,
        package,
        type_path,
        &name,
    ) || retained_trait_surface_impl_items_reference_inherent_assoc_item(
        project,
        reduced,
        render_plan,
        package,
        type_path,
        &name,
    ) || reachable_reduced_callables_macro_tokens_mention_ident(project, reduced, &name)
        || rendered_items_macro_tokens_mention_ident(project, render_plan, &name)
        || retained_root_macro_impl_items_mention_ident(
            project,
            reduced,
            package,
            module_path,
            &name,
        )
}

fn inherent_impl_method_should_render(
    project: &Project,
    reduced: &ReducedProject,
    render_plan: &RenderPlan,
    package: &str,
    _module_path: &[String],
    type_path: &[String],
    item_impl: &syn::ItemImpl,
    name: &str,
) -> bool {
    if !path_item_should_render(render_plan, package, type_path, type_surface_item_kinds()) {
        return false;
    }
    source_include_blocked_impl_method_should_render(
        project,
        reduced,
        render_plan,
        package,
        type_path,
        item_impl,
        name,
    ) || retained_trait_surface_impl_items_reference_inherent_assoc_item(
        project,
        reduced,
        render_plan,
        package,
        type_path,
        name,
    )
}

fn source_include_blocked_impl_method_should_render(
    project: &Project,
    reduced: &ReducedProject,
    render_plan: &RenderPlan,
    package: &str,
    type_path: &[String],
    item_impl: &syn::ItemImpl,
    assoc_name: &str,
) -> bool {
    if !path_item_should_render(render_plan, package, type_path, type_surface_item_kinds())
        || !package_has_generated_source_unknown_surface(project, package)
    {
        return false;
    }
    let method_roots =
        generated_source_unknown_method_roots(project, reduced, render_plan, package);
    if method_roots.is_empty() {
        return false;
    }
    let impl_methods = item_impl
        .items
        .iter()
        .filter_map(|impl_item| {
            let ImplItem::Fn(method) = impl_item else {
                return None;
            };
            (!impl_item_is_test(impl_item)).then_some((method.sig.ident.to_string(), method))
        })
        .collect::<BTreeMap<_, _>>();
    if !impl_methods.contains_key(assoc_name) {
        return false;
    }
    let mut pending = method_roots
        .iter()
        .filter(|method| impl_methods.contains_key(*method))
        .cloned()
        .collect::<Vec<_>>();
    pending.extend(impl_methods.keys().filter_map(|method| {
        (reachable_reduced_callables_reference_inherent_assoc_item(
            project, reduced, package, type_path, method,
        ) || rendered_items_reference_inherent_assoc_item(
            project,
            render_plan,
            package,
            type_path,
            method,
        ))
        .then_some(method.clone())
    }));
    let mut seen = BTreeSet::new();
    while let Some(method_name) = pending.pop() {
        if !seen.insert(method_name.clone()) {
            continue;
        }
        if method_name == assoc_name {
            return true;
        }
        let Some(method) = impl_methods.get(&method_name) else {
            continue;
        };
        for candidate in impl_methods.keys() {
            if !seen.contains(candidate.as_str())
                && (impl_item_fn_has_method_call(method, candidate)
                    || token_method_call_names(&method.to_token_stream()).contains(candidate))
            {
                pending.push(candidate.clone());
            }
        }
    }
    false
}

fn generated_source_unknown_method_roots(
    project: &Project,
    reduced: &ReducedProject,
    render_plan: &RenderPlan,
    package: &str,
) -> BTreeSet<String> {
    let mut roots = BTreeSet::new();
    let source_include_modules = package_source_include_module_names(project, package);
    let package_has_build_script = project
        .workspace
        .packages
        .get(package)
        .and_then(build_script_path)
        .is_some();
    for callable in &reduced.reachable {
        if callable.package() != package {
            continue;
        }
        if let Some(record) = project.functions.get(callable) {
            roots.extend(generated_source_method_roots_from_item_fn(
                &record.item,
                &source_include_modules,
                package_has_build_script,
            ));
        } else if let Some(record) = project.methods.get(callable) {
            roots.extend(generated_source_method_roots_from_impl_item_fn(
                &record.item,
                &source_include_modules,
                package_has_build_script,
            ));
        }
    }
    for (item_id, record) in &project.items {
        if item_id.package != package || !render_plan.item_should_render(item_id) {
            continue;
        }
        roots.extend(generated_source_method_roots_from_item(
            &record.item,
            &source_include_modules,
            package_has_build_script,
        ));
    }
    if source_include_modules.is_empty() && package_has_build_script {
        roots.extend(
            reduced
                .evidence
                .capped_unresolved_method_details
                .iter()
                .filter(|detail| {
                    detail
                        .package
                        .as_deref()
                        .is_none_or(|candidate| candidate == package)
                })
                .map(|detail| detail.method_name.clone()),
        );
    }
    roots
}

fn generated_source_method_roots_from_item_fn(
    item: &syn::ItemFn,
    source_include_modules: &BTreeSet<String>,
    package_has_build_script: bool,
) -> BTreeSet<String> {
    if source_include_modules.is_empty() {
        return package_has_build_script
            .then(|| token_method_call_names(&item.to_token_stream()))
            .unwrap_or_default();
    }
    let mut visitor = SourceIncludeReceiverMethodVisitor {
        source_include_modules,
        method_names: BTreeSet::new(),
    };
    visitor.visit_item_fn(item);
    visitor.method_names
}

fn generated_source_method_roots_from_impl_item_fn(
    item: &syn::ImplItemFn,
    source_include_modules: &BTreeSet<String>,
    package_has_build_script: bool,
) -> BTreeSet<String> {
    if source_include_modules.is_empty() {
        return package_has_build_script
            .then(|| token_method_call_names(&item.to_token_stream()))
            .unwrap_or_default();
    }
    let mut visitor = SourceIncludeReceiverMethodVisitor {
        source_include_modules,
        method_names: BTreeSet::new(),
    };
    visitor.visit_impl_item_fn(item);
    visitor.method_names
}

fn generated_source_method_roots_from_item(
    item: &Item,
    source_include_modules: &BTreeSet<String>,
    package_has_build_script: bool,
) -> BTreeSet<String> {
    if source_include_modules.is_empty() {
        return package_has_build_script
            .then(|| token_method_call_names(&item.to_token_stream()))
            .unwrap_or_default();
    }
    let mut visitor = SourceIncludeReceiverMethodVisitor {
        source_include_modules,
        method_names: BTreeSet::new(),
    };
    visitor.visit_item(item);
    visitor.method_names
}

struct SourceIncludeReceiverMethodVisitor<'a> {
    source_include_modules: &'a BTreeSet<String>,
    method_names: BTreeSet<String>,
}

impl Visit<'_> for SourceIncludeReceiverMethodVisitor<'_> {
    fn visit_expr_method_call(&mut self, node: &syn::ExprMethodCall) {
        if expr_mentions_any_path_root(&node.receiver, self.source_include_modules) {
            self.method_names.insert(node.method.to_string());
        }
        visit::visit_expr_method_call(self, node);
    }
}

fn package_contains_source_include_macro(project: &Project, package: &str) -> bool {
    project_module_paths(project, package)
        .iter()
        .any(|module_path| {
            module_items_for_path(project, package, module_path)
                .is_some_and(|items| items.iter().any(item_contains_source_include_macro))
        })
}

fn package_source_include_module_names(project: &Project, package: &str) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    for module_path in project_module_paths(project, package) {
        let Some(items) = module_items_for_path(project, package, &module_path) else {
            continue;
        };
        for item in items {
            let Item::Mod(item_mod) = item else {
                continue;
            };
            let module_name = item_mod.ident.to_string();
            let mut child_path = module_path.clone();
            child_path.push(module_name.clone());
            let inline_contains = item_mod
                .content
                .as_ref()
                .is_some_and(|(_, items)| items.iter().any(item_contains_source_include_macro));
            let child_contains = module_items_for_path(project, package, &child_path)
                .is_some_and(|items| items.iter().any(item_contains_source_include_macro));
            if inline_contains || child_contains {
                names.insert(module_name);
            }
        }
    }
    names
}

fn item_contains_source_include_macro(item: &Item) -> bool {
    match item {
        Item::Macro(item_macro) => {
            item_macro.ident.is_none() && item_macro.mac.path.is_ident("include")
        }
        Item::Mod(item_mod) => item_mod
            .content
            .as_ref()
            .is_some_and(|(_, items)| items.iter().any(item_contains_source_include_macro)),
        _ => false,
    }
}

fn package_has_generated_source_unknown_surface(project: &Project, package: &str) -> bool {
    package_contains_source_include_macro(project, package)
        || project
            .workspace
            .packages
            .get(package)
            .and_then(build_script_path)
            .is_some()
}

fn trait_item_for_path(project: &Project, package: &str, trait_path: &[String]) -> Option<ItemId> {
    trait_item_for_package_path(project, package, trait_path)
}

fn trait_item_for_package_path(
    project: &Project,
    package: &str,
    trait_path: &[String],
) -> Option<ItemId> {
    let (name, module_path) = trait_path.split_last()?;
    let item = ItemId {
        package: package.to_string(),
        module_path: module_path.to_vec(),
        name: name.clone(),
        kind: ItemKind::Trait,
    };
    project.items.contains_key(&item).then_some(item)
}

fn resolve_trait_path_for_impl(
    project: &Project,
    package: &str,
    module_path: &[String],
    path: &syn::Path,
    aliases: &HashMap<String, Vec<String>>,
) -> Option<(String, Vec<String>)> {
    let segments = apply_alias(
        path.segments
            .iter()
            .map(|segment| segment.ident.to_string())
            .collect(),
        aliases,
    );
    let (trait_package, trait_path) =
        resolve_macro_invocation_segments(project, package, module_path, &segments)?;
    let canonical_module_path = if trait_package == package {
        module_path
    } else {
        &[]
    };
    let trait_path =
        canonical_type_path(project, &trait_package, canonical_module_path, trait_path);
    Some((trait_package, trait_path))
}

fn resolve_callable_trait_path(
    project: &Project,
    package: &str,
    module_path: &[String],
    trait_path: &[String],
    aliases: &HashMap<String, Vec<String>>,
) -> Option<(String, Vec<String>)> {
    if trait_item_for_package_path(project, package, trait_path).is_some() {
        return Some((package.to_string(), trait_path.to_vec()));
    }
    let segments = apply_alias(trait_path.to_vec(), aliases);
    let (trait_package, trait_path) =
        resolve_macro_invocation_segments(project, package, module_path, &segments)?;
    let canonical_module_path = if trait_package == package {
        module_path
    } else {
        &[]
    };
    let trait_path =
        canonical_type_path(project, &trait_package, canonical_module_path, trait_path);
    Some((trait_package, trait_path))
}

fn trait_default_method_is_referenced_by_reachable_callables(
    project: &Project,
    reduced: &ReducedProject,
    trait_item: &ItemId,
) -> bool {
    let Some(record) = project.items.get(trait_item) else {
        return false;
    };
    let Item::Trait(item_trait) = &record.item else {
        return false;
    };
    item_trait.items.iter().any(|item| {
        let TraitItem::Fn(method) = item else {
            return false;
        };
        method.default.is_some()
            && reachable_reduced_callables_mention_ident(
                project,
                reduced,
                &method.sig.ident.to_string(),
            )
    })
}

fn trait_default_method_assoc_item_override_should_render(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    type_path: &[String],
    trait_item: &ItemId,
    assoc_name: &str,
) -> bool {
    if !trait_impl_self_type_is_referenced_by_reachable_surface(
        project, reduced, package, type_path,
    ) {
        return false;
    }
    let Some(record) = project.items.get(trait_item) else {
        return false;
    };
    let Item::Trait(item_trait) = &record.item else {
        return false;
    };
    let trait_path = path_from_item(trait_item);
    item_trait.items.iter().any(|item| {
        let TraitItem::Fn(method) = item else {
            return false;
        };
        let Some(default) = &method.default else {
            return false;
        };
        if !reachable_reduced_callables_mention_ident(
            project,
            reduced,
            &method.sig.ident.to_string(),
        ) {
            return false;
        }
        let mut visitor = TraitAssocPathReferenceVisitor::new(
            project,
            &record.package,
            &record.module_path,
            &record.aliases,
            &trait_item.package,
            &trait_path,
            assoc_name,
            Some((trait_item.package.as_str(), trait_path.as_slice())),
        );
        visitor.visit_block(default);
        visitor.found || token_stream_mentions_ident(&default.to_token_stream(), assoc_name)
    })
}

fn trait_impl_assoc_item_should_remain_for_references_to_trait(
    project: &Project,
    reduced: &ReducedProject,
    target_package: &str,
    target_type_path: &[String],
    target_trait_package: &str,
    target_trait_path: &[String],
    target_trait_input_type_paths: &[Vec<String>],
    assoc_name: &str,
) -> bool {
    reachable_reduced_callables_reference_trait_impl_assoc_item(
        project,
        reduced,
        target_package,
        target_type_path,
        target_trait_package,
        target_trait_path,
        target_trait_input_type_paths,
        assoc_name,
    ) || reachable_items_reference_trait_impl_assoc_item(
        project,
        reduced,
        target_package,
        target_type_path,
        target_trait_package,
        target_trait_path,
        target_trait_input_type_paths,
        assoc_name,
    ) || reachable_reduced_callables_macro_tokens_mention_ident(project, reduced, assoc_name)
        || reachable_items_macro_tokens_mention_ident(project, reduced, assoc_name)
}

fn reachable_reduced_callables_reference_trait_impl_assoc_item(
    project: &Project,
    reduced: &ReducedProject,
    target_package: &str,
    target_type_path: &[String],
    target_trait_package: &str,
    target_trait_path: &[String],
    target_trait_input_type_paths: &[Vec<String>],
    assoc_name: &str,
) -> bool {
    reduced.reachable.iter().any(|callable| {
        if let Some(record) = project.functions.get(callable) {
            let mut visitor = TraitImplAssocPathReferenceVisitor::new(
                project,
                &record.package,
                &record.module_path,
                &record.aliases,
                target_package,
                target_type_path,
                target_trait_package,
                target_trait_path,
                target_trait_input_type_paths,
                assoc_name,
                None,
            );
            visitor.visit_item_fn(&record.item);
            return visitor.found;
        }

        let Some(record) = project.methods.get(callable) else {
            return false;
        };
        let self_impl = match callable {
            CallableId::Method {
                package,
                type_path,
                trait_input_type_paths,
                trait_path: Some(trait_path),
                ..
            } => resolve_callable_trait_path(
                project,
                package,
                &record.module_path,
                trait_path,
                &record.aliases,
            )
            .map(|(trait_package, trait_path)| {
                (
                    package.to_string(),
                    type_path.clone(),
                    trait_package,
                    trait_path,
                    trait_input_type_paths.clone(),
                )
            }),
            _ => None,
        };
        let mut visitor = TraitImplAssocPathReferenceVisitor::new(
            project,
            callable.package(),
            &record.module_path,
            &record.aliases,
            target_package,
            target_type_path,
            target_trait_package,
            target_trait_path,
            target_trait_input_type_paths,
            assoc_name,
            self_impl,
        );
        visitor.visit_impl_item_fn(&record.item);
        visitor.found
    })
}

fn reachable_items_reference_trait_impl_assoc_item(
    project: &Project,
    reduced: &ReducedProject,
    target_package: &str,
    target_type_path: &[String],
    target_trait_package: &str,
    target_trait_path: &[String],
    target_trait_input_type_paths: &[Vec<String>],
    assoc_name: &str,
) -> bool {
    reduced.reachable_items.iter().any(|item_id| {
        let Some(record) = project.items.get(item_id) else {
            return false;
        };
        let mut visitor = TraitImplAssocPathReferenceVisitor::new(
            project,
            &record.package,
            &record.module_path,
            &record.aliases,
            target_package,
            target_type_path,
            target_trait_package,
            target_trait_path,
            target_trait_input_type_paths,
            assoc_name,
            None,
        );
        visitor.visit_item(&record.item);
        visitor.found
    })
}

fn trait_impl_self_type_is_referenced_by_reachable_surface(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    type_path: &[String],
) -> bool {
    path_item_is_reachable(
        reduced,
        package,
        type_path,
        &[
            ItemKind::Struct,
            ItemKind::Enum,
            ItemKind::Union,
            ItemKind::Type,
        ],
    ) || type_path
        .last()
        .is_some_and(|name| reachable_reduced_callables_mention_ident(project, reduced, name))
}

fn type_tokens_are_referenced_by_reachable_callables(
    project: &Project,
    reduced: &ReducedProject,
    ty: &Type,
) -> bool {
    let mut idents = BTreeSet::new();
    collect_token_idents(&ty.to_token_stream(), &mut idents);
    idents
        .iter()
        .any(|ident| reachable_reduced_callables_mention_ident(project, reduced, ident))
}

fn trait_impl_item_is_required_by_trait(
    project: &Project,
    trait_item: &ItemId,
    impl_item: &ImplItem,
) -> bool {
    let Some(record) = project.items.get(trait_item) else {
        return false;
    };
    let Item::Trait(item_trait) = &record.item else {
        return false;
    };
    match impl_item {
        ImplItem::Fn(method) => item_trait.items.iter().any(|trait_item| {
            let TraitItem::Fn(function) = trait_item else {
                return false;
            };
            function.sig.ident == method.sig.ident && function.default.is_none()
        }),
        ImplItem::Const(item) => item_trait.items.iter().any(|trait_item| {
            let TraitItem::Const(constant) = trait_item else {
                return false;
            };
            constant.ident == item.ident && constant.default.is_none()
        }),
        ImplItem::Type(item) => item_trait.items.iter().any(|trait_item| {
            let TraitItem::Type(associated_type) = trait_item else {
                return false;
            };
            associated_type.ident == item.ident && associated_type.default.is_none()
        }),
        _ => false,
    }
}

fn impl_item_attrs_require_surface_retention(impl_item: &ImplItem) -> bool {
    match impl_item {
        ImplItem::Const(item) => item.attrs.iter().any(attr_requires_impl_surface_retention),
        ImplItem::Fn(item) => item.attrs.iter().any(attr_requires_impl_surface_retention),
        ImplItem::Macro(item) => item.attrs.iter().any(attr_requires_impl_surface_retention),
        ImplItem::Type(item) => item.attrs.iter().any(attr_requires_impl_surface_retention),
        ImplItem::Verbatim(_) => false,
        _ => false,
    }
}

fn root_item_impl_surface_should_render(
    reduced: &ReducedProject,
    package: &str,
    type_path: &[String],
    item_impl: &syn::ItemImpl,
) -> bool {
    item_impl.trait_.is_none()
        && path_item_is_root(
            reduced,
            package,
            type_path,
            &[
                ItemKind::Struct,
                ItemKind::Enum,
                ItemKind::Union,
                ItemKind::Type,
            ],
        )
        && impl_surface_has_macro_contract_attrs(item_impl)
}

fn root_macro_impl_surface_should_render_for_module(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    module_path: &[String],
    item_impl: &syn::ItemImpl,
    aliases: &HashMap<String, Vec<String>>,
) -> bool {
    resolved_local_type_path(project, package, module_path, &item_impl.self_ty, aliases)
        .is_some_and(|type_path| {
            root_item_impl_surface_should_render(reduced, package, &type_path, item_impl)
        })
}

fn impl_surface_has_macro_contract_attrs(item_impl: &syn::ItemImpl) -> bool {
    item_impl
        .attrs
        .iter()
        .any(attr_requires_impl_surface_retention)
        || item_impl.items.iter().any(|item| match item {
            ImplItem::Const(item) => item.attrs.iter().any(attr_requires_impl_surface_retention),
            ImplItem::Fn(item) => item.attrs.iter().any(attr_requires_impl_surface_retention),
            ImplItem::Macro(item) => item.attrs.iter().any(attr_requires_impl_surface_retention),
            ImplItem::Type(item) => item.attrs.iter().any(attr_requires_impl_surface_retention),
            ImplItem::Verbatim(_) => false,
            _ => false,
        })
}

fn root_macro_impl_item_should_render(item_impl: &syn::ItemImpl, impl_item: &ImplItem) -> bool {
    if item_impl
        .attrs
        .iter()
        .any(attr_requires_impl_surface_retention)
    {
        return true;
    }

    match impl_item {
        ImplItem::Const(item) => item.attrs.iter().any(attr_requires_impl_surface_retention),
        ImplItem::Fn(item) => {
            matches!(item.vis, syn::Visibility::Public(_))
                || item.attrs.iter().any(attr_requires_impl_surface_retention)
        }
        ImplItem::Macro(item) => item.attrs.iter().any(attr_requires_impl_surface_retention),
        ImplItem::Type(item) => item.attrs.iter().any(attr_requires_impl_surface_retention),
        ImplItem::Verbatim(_) => false,
        _ => false,
    }
}

fn attr_requires_impl_surface_retention(attribute: &syn::Attribute) -> bool {
    let Some(first) = attribute.path().segments.first() else {
        return false;
    };
    if first.ident == "cfg_attr" {
        let tokens = attribute.to_token_stream();
        return token_stream_mentions_ident(&tokens, "uniffi")
            && token_stream_mentions_ident(&tokens, "export");
    }
    !matches!(
        first.ident.to_string().as_str(),
        "allow"
            | "automatically_derived"
            | "cfg"
            | "cfg_attr"
            | "cold"
            | "deny"
            | "deprecated"
            | "doc"
            | "forbid"
            | "inline"
            | "must_use"
            | "opensourced"
            | "repr"
            | "test"
            | "warn"
    )
}

fn trait_impl_items_are_reachable(
    reduced: &ReducedProject,
    package: &str,
    type_path: &[String],
    trait_path: &[String],
) -> bool {
    path_item_is_reachable(
        reduced,
        package,
        type_path,
        &[
            ItemKind::Struct,
            ItemKind::Enum,
            ItemKind::Union,
            ItemKind::Type,
        ],
    ) && path_item_is_reachable(reduced, package, trait_path, &[ItemKind::Trait])
}

fn reachable_trait_impl_method_for_type_named(
    reduced: &ReducedProject,
    package: &str,
    type_path: &[String],
    trait_name: &str,
) -> bool {
    reduced.reachable.iter().any(|callable| {
        let CallableId::Method {
            package: callable_package,
            type_path: callable_type,
            trait_path: Some(trait_path),
            ..
        } = callable
        else {
            return false;
        };
        callable_package == package
            && callable_type == type_path
            && trait_path.last().is_some_and(|name| name == trait_name)
    })
}

fn marker_trait_impl_should_remain(
    reduced: &ReducedProject,
    package: &str,
    type_path: &[String],
    trait_name: &str,
) -> bool {
    if !path_item_is_reachable(
        reduced,
        package,
        type_path,
        &[
            ItemKind::Struct,
            ItemKind::Enum,
            ItemKind::Union,
            ItemKind::Type,
        ],
    ) {
        return false;
    }
    match trait_name {
        "Eq" => reachable_trait_impl_method_for_type_named(reduced, package, type_path, "Ord"),
        "Error" => true,
        "RefUnwindSafe" | "Send" | "Sync" | "Unpin" | "UnwindSafe" => true,
        _ => false,
    }
}

fn path_item_is_reachable(
    reduced: &ReducedProject,
    package: &str,
    path: &[String],
    kinds: &[ItemKind],
) -> bool {
    let Some((name, module_path)) = path.split_last() else {
        return false;
    };
    kinds.iter().any(|kind| {
        reduced.reachable_items.contains(&ItemId {
            package: package.to_string(),
            module_path: module_path.to_vec(),
            name: name.clone(),
            kind: *kind,
        })
    })
}

fn path_item_is_blocked_by_unknown(
    usage: &UsageDecisionIndex,
    package: &str,
    path: &[String],
    kinds: &[ItemKind],
) -> bool {
    let Some((name, module_path)) = path.split_last() else {
        return false;
    };
    kinds.iter().any(|kind| {
        usage.is_blocked_by_unknown_item(&ItemId {
            package: package.to_string(),
            module_path: module_path.to_vec(),
            name: name.clone(),
            kind: *kind,
        })
    })
}

fn path_item_should_render(
    render_plan: &RenderPlan,
    package: &str,
    path: &[String],
    kinds: &[ItemKind],
) -> bool {
    let Some((name, module_path)) = path.split_last() else {
        return false;
    };
    kinds.iter().any(|kind| {
        render_plan.item_should_render(&ItemId {
            package: package.to_string(),
            module_path: module_path.to_vec(),
            name: name.clone(),
            kind: *kind,
        })
    })
}

fn external_trait_impl_type_surface_is_required(
    render_plan: &RenderPlan,
    package: &str,
    type_path: &[String],
    trait_path: Option<&[String]>,
    trait_item: Option<&ItemId>,
) -> bool {
    trait_path.is_some()
        && trait_item.is_none()
        && path_item_should_render(render_plan, package, type_path, type_surface_item_kinds())
}

fn type_surface_item_kinds() -> &'static [ItemKind] {
    &[
        ItemKind::Struct,
        ItemKind::Enum,
        ItemKind::Union,
        ItemKind::Type,
    ]
}

fn path_item_is_root(
    reduced: &ReducedProject,
    package: &str,
    path: &[String],
    kinds: &[ItemKind],
) -> bool {
    let Some((name, module_path)) = path.split_last() else {
        return false;
    };
    kinds.iter().any(|kind| {
        reduced.roots.iter().any(|root| {
            matches!(
                root,
                RootId::Item(item)
                    if item.package == package
                        && item.module_path == module_path
                        && item.name == *name
                        && item.kind == *kind
            )
        })
    })
}

fn reachable_module_mentions_ident(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    module_path: &[String],
    ident: &str,
) -> bool {
    reduced
        .reachable
        .iter()
        .filter(|callable| callable.package() == package)
        .any(|callable| {
            project.functions.get(callable).is_some_and(|record| {
                record.module_path == module_path
                    && (callable_mentions_ident(callable, ident)
                        || token_stream_mentions_ident(&record.item.to_token_stream(), ident))
            }) || project.methods.get(callable).is_some_and(|record| {
                record.module_path == module_path
                    && (callable_mentions_ident(callable, ident)
                        || token_stream_mentions_ident(&record.item.to_token_stream(), ident))
            })
        })
        || reduced
            .reachable_items
            .iter()
            .filter(|item| item.package() == package && item.module_path == module_path)
            .any(|item| {
                project.items.get(item).is_some_and(|record| {
                    reachable_item_mentions_ident(project, reduced, package, item, record, ident)
                })
            })
        || retained_impl_attrs_mention_ident(project, reduced, package, module_path, ident)
        || retained_impl_non_fn_items_mention_ident(
            project,
            reduced,
            None,
            package,
            module_path,
            ident,
        )
        || retained_root_macro_impl_items_mention_ident(
            project,
            reduced,
            package,
            module_path,
            ident,
        )
        || retained_macro_invocations_mention_ident(project, reduced, package, module_path, ident)
}

fn reachable_module_mentions_unqualified_ident(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    module_path: &[String],
    ident: &str,
) -> bool {
    reduced
        .reachable
        .iter()
        .filter(|callable| callable.package() == package)
        .any(|callable| {
            project.functions.get(callable).is_some_and(|record| {
                record.module_path == module_path
                    && token_stream_mentions_unqualified_ident(
                        &record.item.to_token_stream(),
                        ident,
                    )
            }) || project.methods.get(callable).is_some_and(|record| {
                record.module_path == module_path
                    && token_stream_mentions_unqualified_ident(
                        &record.item.to_token_stream(),
                        ident,
                    )
            })
        })
        || reduced
            .reachable_items
            .iter()
            .filter(|item| item.package() == package && item.module_path == module_path)
            .any(|item| {
                project.items.get(item).is_some_and(|record| {
                    reachable_item_mentions_unqualified_ident(
                        project, reduced, package, item, record, ident,
                    )
                })
            })
        || retained_impl_attrs_mention_unqualified_ident(
            project,
            reduced,
            None,
            package,
            module_path,
            ident,
        )
        || retained_impl_non_fn_items_mention_unqualified_ident(
            project,
            reduced,
            None,
            package,
            module_path,
            ident,
        )
        || retained_root_macro_impl_items_mention_unqualified_ident(
            project,
            reduced,
            package,
            module_path,
            ident,
        )
        || retained_macro_definitions_mention_unqualified_ident(
            project,
            reduced,
            None,
            package,
            module_path,
            ident,
        )
        || retained_macro_invocations_mention_unqualified_ident(
            project,
            reduced,
            package,
            module_path,
            ident,
        )
        || retained_foreign_items_mention_unqualified_ident(
            project,
            reduced,
            package,
            module_path,
            ident,
        )
}

fn reachable_module_has_method_call(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    module_path: &[String],
    method: &str,
) -> bool {
    reduced
        .reachable
        .iter()
        .filter(|callable| callable.package() == package)
        .any(|callable| {
            project.functions.get(callable).is_some_and(|record| {
                record.module_path == module_path && item_fn_has_method_call(&record.item, method)
            }) || project.methods.get(callable).is_some_and(|record| {
                record.module_path == module_path
                    && impl_item_fn_has_method_call(&record.item, method)
            })
        })
        || reduced
            .reachable_items
            .iter()
            .filter(|item| item.package() == package && item.module_path == module_path)
            .any(|item| {
                project
                    .items
                    .get(item)
                    .is_some_and(|record| item_has_method_call(&record.item, method))
            })
}

fn reachable_import_scope_has_method_call(
    project: &Project,
    reduced: &ReducedProject,
    render_plan: &RenderPlan,
    package: &str,
    module_path: &[String],
    method: &str,
) -> bool {
    if reachable_module_has_method_call(project, reduced, package, module_path, method) {
        return true;
    }
    child_modules_with_super_glob_import(project, reduced, render_plan, package, module_path)
        .into_iter()
        .any(|child_path| {
            reachable_import_scope_has_method_call(
                project,
                reduced,
                render_plan,
                package,
                &child_path,
                method,
            )
        })
}

fn reachable_module_has_associated_function_call(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    module_path: &[String],
    function: &str,
) -> bool {
    reduced
        .reachable
        .iter()
        .filter(|callable| callable.package() == package)
        .any(|callable| {
            project.functions.get(callable).is_some_and(|record| {
                record.module_path == module_path
                    && item_fn_has_associated_function_call(&record.item, function)
            }) || project.methods.get(callable).is_some_and(|record| {
                record.module_path == module_path
                    && impl_item_fn_has_associated_function_call(&record.item, function)
            })
        })
        || reduced
            .reachable_items
            .iter()
            .filter(|item| item.package() == package && item.module_path == module_path)
            .any(|item| {
                project
                    .items
                    .get(item)
                    .is_some_and(|record| item_has_associated_function_call(&record.item, function))
            })
}

fn reachable_import_scope_has_associated_function_call(
    project: &Project,
    reduced: &ReducedProject,
    render_plan: &RenderPlan,
    package: &str,
    module_path: &[String],
    function: &str,
) -> bool {
    if reachable_module_has_associated_function_call(
        project,
        reduced,
        package,
        module_path,
        function,
    ) {
        return true;
    }
    child_modules_with_super_glob_import(project, reduced, render_plan, package, module_path)
        .into_iter()
        .any(|child_path| {
            reachable_import_scope_has_associated_function_call(
                project,
                reduced,
                render_plan,
                package,
                &child_path,
                function,
            )
        })
}

fn root_macro_impl_assoc_function_calls(
    project: &Project,
    reduced: &ReducedProject,
) -> RootMacroImplAssocFunctionCalls {
    let mut calls = BTreeSet::new();
    for package in &reduced.packages {
        for module_path in project_module_paths(project, package) {
            let Some(items) = module_items_for_path(project, package, &module_path) else {
                continue;
            };
            let aliases = project
                .module_aliases
                .get(&(package.to_string(), module_path.clone()))
                .cloned()
                .unwrap_or_default();
            for item in items {
                let Item::Impl(item_impl) = item else {
                    continue;
                };
                let Some(type_path) = resolved_local_type_path(
                    project,
                    package,
                    &module_path,
                    &item_impl.self_ty,
                    &aliases,
                ) else {
                    continue;
                };
                if !root_item_impl_surface_should_render(reduced, package, &type_path, item_impl) {
                    continue;
                }
                for impl_item in &item_impl.items {
                    let ImplItem::Fn(method) = impl_item else {
                        continue;
                    };
                    if impl_item_is_test(impl_item)
                        || !root_macro_impl_item_should_render(item_impl, impl_item)
                    {
                        continue;
                    }
                    calls.extend(
                        associated_function_calls_on_types(method)
                            .into_iter()
                            .map(|(type_name, function)| (package.clone(), type_name, function)),
                    );
                }
            }
        }
    }
    calls
}

fn root_macro_impl_assoc_function_calls_contains(
    calls: &RootMacroImplAssocFunctionCalls,
    package: &str,
    type_path: &[String],
    function: &str,
) -> bool {
    let Some(type_name) = type_path.last() else {
        return false;
    };
    calls.contains(&(package.to_string(), type_name.clone(), function.to_string()))
}

fn retained_impl_surfaces_call_inherent_associated_function(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    type_path: &[String],
    function: &str,
) -> bool {
    let Some(type_name) = type_path.last() else {
        return false;
    };

    project_module_paths(project, package)
        .into_iter()
        .any(|module_path| {
            if !reduced.packages.contains(package) {
                return false;
            }
            let Some(items) = module_items_for_path(project, package, &module_path) else {
                return false;
            };
            let aliases = project
                .module_aliases
                .get(&(package.to_string(), module_path.clone()))
                .cloned()
                .unwrap_or_default();

            items.iter().any(|item| {
                let Item::Impl(item_impl) = item else {
                    return false;
                };
                if !root_macro_impl_surface_should_render_for_module(
                    project,
                    reduced,
                    package,
                    &module_path,
                    item_impl,
                    &aliases,
                ) {
                    return false;
                }
                item_impl.items.iter().any(|impl_item| {
                    let ImplItem::Fn(method) = impl_item else {
                        return false;
                    };
                    !impl_item_is_test(impl_item)
                        && root_macro_impl_item_should_render(item_impl, impl_item)
                        && impl_item_fn_has_associated_function_call_on_type(
                            method, type_name, function,
                        )
                })
            })
        })
}

fn child_modules_with_super_glob_import(
    project: &Project,
    reduced: &ReducedProject,
    render_plan: &RenderPlan,
    package: &str,
    module_path: &[String],
) -> Vec<Vec<String>> {
    let mut children = Vec::new();
    if let Some(source) = project
        .files
        .values()
        .find(|source| source.package == package && source.module_path == module_path)
    {
        for item in &source.syntax.items {
            let Item::Mod(item_mod) = item else {
                continue;
            };
            let Some((_, child_items)) = &item_mod.content else {
                continue;
            };
            if !items_have_super_glob_import(child_items) {
                continue;
            }
            let mut child_path = module_path.to_vec();
            child_path.push(item_mod.ident.to_string());
            if module_should_render(project, reduced, render_plan, package, &child_path) {
                children.push(child_path);
            }
        }
    }

    children.extend(
        project
            .files
            .values()
            .filter(|source| source.package == package)
            .filter(|source| source.module_path.len() == module_path.len() + 1)
            .filter(|source| path_has_prefix(&source.module_path, module_path))
            .filter(|source| {
                module_should_render(project, reduced, render_plan, package, &source.module_path)
                    && items_have_super_glob_import(&source.syntax.items)
            })
            .map(|source| source.module_path.clone()),
    );
    children.sort();
    children.dedup();
    children
}

fn item_fn_has_method_call(item: &syn::ItemFn, method: &str) -> bool {
    let mut visitor = MethodCallVisitor::new(method);
    visitor.visit_item_fn(item);
    visitor.found
}

fn impl_item_fn_has_method_call(item: &syn::ImplItemFn, method: &str) -> bool {
    let mut visitor = MethodCallVisitor::new(method);
    visitor.visit_impl_item_fn(item);
    visitor.found
}

fn item_has_method_call(item: &Item, method: &str) -> bool {
    if matches!(item, Item::Mod(_)) {
        return false;
    }
    let mut visitor = MethodCallVisitor::new(method);
    visitor.visit_item(item);
    visitor.found
}

fn item_fn_has_associated_function_call(item: &syn::ItemFn, function: &str) -> bool {
    let mut visitor = AssociatedFunctionCallVisitor::new(function);
    visitor.visit_item_fn(item);
    visitor.found
}

fn impl_item_fn_has_associated_function_call(item: &syn::ImplItemFn, function: &str) -> bool {
    let mut visitor = AssociatedFunctionCallVisitor::new(function);
    visitor.visit_impl_item_fn(item);
    visitor.found
}

fn impl_item_fn_has_associated_function_call_on_type(
    item: &syn::ImplItemFn,
    type_name: &str,
    function: &str,
) -> bool {
    let mut visitor = AssociatedFunctionCallOnTypeVisitor::new(type_name, function);
    visitor.visit_impl_item_fn(item);
    visitor.found
}

fn associated_function_calls_on_types(item: &syn::ImplItemFn) -> BTreeSet<(String, String)> {
    let mut visitor = AssociatedFunctionCallsOnTypesVisitor::default();
    visitor.visit_impl_item_fn(item);
    visitor.calls
}

fn item_has_associated_function_call(item: &Item, function: &str) -> bool {
    if matches!(item, Item::Mod(_)) {
        return false;
    }
    let mut visitor = AssociatedFunctionCallVisitor::new(function);
    visitor.visit_item(item);
    visitor.found
}

struct MethodCallVisitor<'a> {
    method: &'a str,
    found: bool,
}

impl<'a> MethodCallVisitor<'a> {
    fn new(method: &'a str) -> Self {
        Self {
            method,
            found: false,
        }
    }
}

impl Visit<'_> for MethodCallVisitor<'_> {
    fn visit_expr_method_call(&mut self, node: &syn::ExprMethodCall) {
        if node.method == self.method {
            self.found = true;
            return;
        }
        visit::visit_expr_method_call(self, node);
    }
}

struct AssociatedFunctionCallVisitor<'a> {
    function: &'a str,
    generic_type_params: BTreeSet<String>,
    found: bool,
}

impl<'a> AssociatedFunctionCallVisitor<'a> {
    fn new(function: &'a str) -> Self {
        Self {
            function,
            generic_type_params: BTreeSet::new(),
            found: false,
        }
    }
}

impl Visit<'_> for AssociatedFunctionCallVisitor<'_> {
    fn visit_generics(&mut self, node: &syn::Generics) {
        self.generic_type_params
            .extend(node.type_params().map(|param| param.ident.to_string()));
        visit::visit_generics(self, node);
    }

    fn visit_expr_call(&mut self, node: &syn::ExprCall) {
        if let syn::Expr::Path(path) = node.func.as_ref() {
            if path.path.segments.len() > 1
                && path
                    .path
                    .segments
                    .last()
                    .is_some_and(|segment| segment.ident == self.function)
                && !associated_function_call_receiver_is_generic_param(
                    &path.path,
                    &self.generic_type_params,
                )
            {
                self.found = true;
                return;
            }
        }
        visit::visit_expr_call(self, node);
    }
}

fn associated_function_call_receiver_is_generic_param(
    path: &syn::Path,
    generic_type_params: &BTreeSet<String>,
) -> bool {
    if path.segments.len() != 2 {
        return false;
    }
    path.segments
        .first()
        .is_some_and(|segment| generic_type_params.contains(&segment.ident.to_string()))
}

struct AssociatedFunctionCallOnTypeVisitor<'a> {
    type_name: &'a str,
    function: &'a str,
    found: bool,
}

impl<'a> AssociatedFunctionCallOnTypeVisitor<'a> {
    fn new(type_name: &'a str, function: &'a str) -> Self {
        Self {
            type_name,
            function,
            found: false,
        }
    }
}

impl Visit<'_> for AssociatedFunctionCallOnTypeVisitor<'_> {
    fn visit_expr_call(&mut self, node: &syn::ExprCall) {
        if let syn::Expr::Path(path) = node.func.as_ref() {
            let segments = path.path.segments.iter().collect::<Vec<_>>();
            if segments.len() > 1
                && segments
                    .last()
                    .is_some_and(|segment| segment.ident == self.function)
                && segments[..segments.len() - 1]
                    .iter()
                    .any(|segment| segment.ident == self.type_name)
            {
                self.found = true;
                return;
            }
        }
        visit::visit_expr_call(self, node);
    }
}

#[derive(Default)]
struct AssociatedFunctionCallsOnTypesVisitor {
    calls: BTreeSet<(String, String)>,
}

impl Visit<'_> for AssociatedFunctionCallsOnTypesVisitor {
    fn visit_expr_call(&mut self, node: &syn::ExprCall) {
        if let syn::Expr::Path(path) = node.func.as_ref() {
            let segments = path.path.segments.iter().collect::<Vec<_>>();
            if let Some(function) = segments.last().filter(|_| segments.len() > 1) {
                for type_segment in &segments[..segments.len() - 1] {
                    self.calls
                        .insert((type_segment.ident.to_string(), function.ident.to_string()));
                }
            }
        }
        visit::visit_expr_call(self, node);
    }
}

fn reachable_item_mentions_ident(
    project: &Project,
    reduced: &ReducedProject,
    package: &str,
    item_id: &ItemId,
    record: &crate::model::ItemRecord,
    ident: &str,
) -> bool {
    if let Item::Trait(item_trait) = &record.item {
        if root_item_should_render(reduced, item_id) {
            return token_stream_mentions_ident(&record.item.to_token_stream(), ident);
        }
        return trait_type_surface_mentions_ident(
            project, reduced, package, item_id, item_trait, ident,
        );
    }

    let Item::Struct(item_struct) = &record.item else {
        return token_stream_mentions_ident(&record.item.to_token_stream(), ident);
    };
    if item_id.name == ident || item_id.module_path.iter().any(|segment| segment == ident) {
        return true;
    }
    if item_struct
        .attrs
        .iter()
        .any(|attr| token_stream_mentions_ident(&attr.to_token_stream(), ident))
    {
        return true;
    }
    if token_stream_mentions_ident(&item_struct.generics.to_token_stream(), ident) {
        return true;
    }
    if root_item_should_render(reduced, item_id) {
        return token_stream_mentions_ident(&record.item.to_token_stream(), ident);
    }

    let syn::Fields::Named(fields) = &item_struct.fields else {
        return token_stream_mentions_ident(&record.item.to_token_stream(), ident);
    };
    fields.named.iter().any(|field| {
        struct_field_should_remain(
            project,
            reduced,
            None,
            package,
            &item_id.module_path,
            item_struct,
            field,
        ) && token_stream_mentions_ident(&field.to_token_stream(), ident)
    })
}

